from __future__ import annotations
import json
from pathlib import Path
import streamlit as st
import streamlit.components.v1 as components

APP_VERSION = "3.3.0"

st.set_page_config(page_title="AI Stocks Made Simple", page_icon="⚡", layout="wide", initial_sidebar_state="collapsed")
st.markdown("""
<style>
.block-container{padding:.35rem .45rem 0!important;max-width:960px!important}.stApp{background:#020711}header,footer{visibility:hidden}
[data-testid="stImage"]{margin:0!important}[data-testid="stImage"] img{width:100%!important;border-radius:24px;border:1px solid #244e80;box-shadow:0 0 32px #0ea5e938;background:#020711;display:block}
.hero-note{margin:.35rem 0 .5rem;padding:8px 12px;border:1px solid #17365f;border-radius:12px;background:#07111f;color:#9fb4ce;font-size:.75rem;text-align:center}.hero-note b{color:#22d3ee}
</style>
""", unsafe_allow_html=True)

def latest_snapshot():
    p = Path("data/historical/rankings")
    files = sorted(p.glob("*.json")) if p.exists() else []
    if not files:
        return [], "unavailable"
    try:
        return json.loads(files[-1].read_text(encoding="utf-8")), files[-1].stem
    except Exception:
        return [], "unavailable"

rows, snapshot = latest_snapshot()
rows = sorted(rows, key=lambda r: r.get("rank", 999))[:20]
if not rows:
    st.error("The saved Top-20 ranking snapshot could not be loaded.")
    st.stop()

names = {"MU":"Micron","TSM":"TSMC","CRDO":"Credo","ANET":"Arista Networks","PLTR":"Palantir","TER":"Teradyne","NVDA":"NVIDIA","DELL":"Dell","PATH":"UiPath","AMD":"AMD","GOOGL":"Alphabet","AMAT":"Applied Materials","DDOG":"Datadog","AVGO":"Broadcom","SNOW":"Snowflake","AMZN":"Amazon","MDB":"MongoDB","NET":"Cloudflare","ACMR":"ACM Research","VRT":"Vertiv","ASML":"ASML","SMCI":"Super Micro Computer","MSFT":"Microsoft","PANW":"Palo Alto Networks","ARM":"Arm","META":"Meta","CRWD":"CrowdStrike","MRVL":"Marvell","NOW":"ServiceNow","ORCL":"Oracle"}
stocks=[]
for r in rows:
    t=r.get("ticker","")
    stocks.append({"rank":r.get("rank",0),"ticker":t,"name":names.get(t,t),"score":round(float(r.get("score",0) or 0),1),"price":round(float(r.get("price",0) or 0),2),"risk":r.get("risk","—")})

# v3.3 uses a small purpose-built hero generated for the actual phone layout.
# It is a local repo asset, so there is no external URL, iframe image, or base64 decode at runtime.
hero_path=Path("assets/hero_v3_mobile.jpg")
if hero_path.exists():
    st.image(str(hero_path),use_container_width=True)
else:
    st.warning("Hero artwork is being updated.")
st.markdown(f"<div class='hero-note'><b>VERSION {APP_VERSION}</b> • AI-powered paycheck investing simulator • ranking snapshot {snapshot}</div>",unsafe_allow_html=True)

stocks_json=json.dumps(stocks)

# Preserve the complete v3.2 interactive simulator below the rebuilt hero.
# Load the simulator body from the prior implementation stored inline below.
html = f'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><style>
*{{box-sizing:border-box}}html,body{{margin:0;background:#020711;color:#edf7ff;font-family:Arial,Helvetica,sans-serif}}body{{padding:8px 4px 90px}}.app{{max-width:920px;margin:auto}}.cyan{{color:#22d3ee}}.green{{color:#4ade80}}.muted{{color:#8fa6bf;font-size:13px}}.status{{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:4px 0 12px}}.stat,.panel{{background:linear-gradient(180deg,#081322,#030812);border:1px solid #17365f;border-radius:18px;padding:14px;margin:10px 0}}.stat small{{display:block;color:#8fa6bf;font-size:9px;font-weight:900}}.stat strong{{font-size:16px}}h2{{margin:0 0 5px;font-size:24px}}.stocks{{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin-top:12px}}.stock{{display:flex;align-items:center;gap:10px;text-align:left;background:#07111f;border:1px solid #17365f;border-radius:15px;padding:12px;color:white;cursor:pointer}}.stock.active{{border-color:#22d3ee;background:#09253b;box-shadow:0 0 18px #22d3ee33}}.badge{{min-width:38px;height:38px;border-radius:50%;display:grid;place-items:center;border:2px solid #22c55e;color:#4ade80;font-weight:900}}.stockMain{{flex:1}}.stockName{{font-weight:900}}.ticker{{color:#8fa6bf;font-size:12px}}.price{{font-weight:900}}.plan{{background:radial-gradient(circle at 10% 15%,#ec489944,transparent 27%),linear-gradient(120deg,#24104d,#07345b,#481c08);border-color:#a855f7}}label{{display:block;font-size:12px;font-weight:900;color:#b7c9dd;margin:12px 0 6px}}select,input{{width:100%;background:#06101d;border:1px solid #315177;color:white;border-radius:13px;padding:13px;font-size:16px}}.quick{{display:grid;grid-template-columns:repeat(5,1fr);gap:6px}}button{{border:1px solid #275078;border-radius:13px;background:#07111f;color:white;padding:12px;font-weight:900;cursor:pointer}}button.active,button.primary{{background:linear-gradient(90deg,#0ea5e9,#7c3aed);border-color:#22d3ee}}.mode{{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}}.two{{display:grid;grid-template-columns:1fr 1fr;gap:10px}}.selected{{margin-top:10px;background:#052d23;border:1px solid #22c55e;border-radius:14px;padding:12px;font-weight:900}}.rotation{{display:none;margin-top:10px;padding:12px;border:1px solid #7c3aed;border-radius:15px;background:#120b2b}}.rotation.show{{display:block}}.rotgrid{{display:grid;grid-template-columns:1fr 1fr;gap:8px}}.route{{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}}.pill{{padding:7px 10px;border-radius:999px;background:#0a2338;border:1px solid #22d3ee;color:#b8efff;font-size:12px;font-weight:900}}.results{{display:none}}.results.show{{display:block}}.cards{{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}}.card,.upcoming,.breakdown{{background:#07111f;border:1px solid #17365f;border-radius:15px;padding:12px}}.card small{{display:block;color:#8fa6bf;font-size:9px}}.card strong{{font-size:19px}}.deposit,.breakrow{{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #14263a;font-size:13px}}.ref{{border:1px solid #22c55e;background:linear-gradient(120deg,#052e16,#07182c);border-radius:18px;padding:15px;margin-top:12px}}.ref a{{display:block;text-align:center;text-decoration:none;background:#22c55e;color:#03210f;font-weight:1000;border-radius:13px;padding:13px;margin-top:10px}}@media(max-width:650px){{.status{{grid-template-columns:repeat(2,1fr)}}.stocks{{grid-template-columns:1fr}}.cards{{grid-template-columns:repeat(2,1fr)}}.rotgrid{{grid-template-columns:1fr}}}}
</style></head><body><div class="app"><div class="status"><div class="stat"><small>MARKET MODEL</small><strong class="green">ACTIVE</strong></div><div class="stat"><small>TOP STOCKS</small><strong>20 AI NAMES</strong></div><div class="stat"><small>MODEL VERSION</small><strong class="cyan">3.3</strong></div><div class="stat"><small>SNAPSHOT</small><strong>{snapshot}</strong></div></div><section class="panel plan" id="sim"><h2>🎯 BUILD YOUR PLAN</h2><div class="muted">Buy one stock every payday — or rotate different AI stocks from check to check.</div><div class="mode"><button id="oneBtn" class="active" onclick="setMode('one')">ONE STOCK</button><button id="rotBtn" onclick="setMode('rotation')">ROTATION MODE</button></div><div id="selected" class="selected">Select a stock below to start.</div><div id="rotation" class="rotation"><b>YOUR PAYCHECK ROTATION</b><div class="muted">Choose 2–5 stocks in the order you want to buy them.</div><div class="rotgrid"><div><label>ADD STOCK</label><select id="rotSelect"></select></div><div><label>&nbsp;</label><button onclick="addRotation()">+ ADD TO ROTATION</button></div></div><div id="route" class="route"></div><button style="margin-top:8px" onclick="clearRotation()">CLEAR ROTATION</button></div><label>AMOUNT PER PAYCHECK</label><div class="quick">{''.join(f'<button onclick="setAmt({a})">${a}</button>' for a in [5,10,25,50,100])}</div><input id="amount" type="number" min="1" step="1" value="10"><div class="two"><div><label>FREQUENCY</label><select id="freq"><option value="14">Every 2 Weeks (Paycheck)</option><option value="7">Every Friday / Weekly</option><option value="30">Monthly</option></select></div><div><label>START DATE</label><input id="start" type="date"></div></div><label>END DATE</label><input id="end" type="date" value="2026-12-31"><button class="primary" style="width:100%;margin-top:14px" onclick="calculate()">SHOW ME HOW THIS ADDS UP →</button></section><section class="panel"><h2>🏆 TOP 20 AI STOCKS</h2><div class="muted">Tap any stock to make it your single-stock plan, or add it to Rotation Mode.</div><div class="stocks" id="stocks"></div></section><section id="results" class="panel results"><h2 id="resultTitle">YOUR PLAN</h2><div class="cards"><div class="card"><small>TOTAL CONTRIBUTIONS</small><strong id="contrib">$0</strong></div><div class="card"><small>NUMBER OF DEPOSITS</small><strong id="deposits">0</strong></div><div class="card"><small>EST. VALUE AT DISPLAYED PRICES</small><strong id="value">$0</strong></div><div class="card"><small>STOCKS IN PLAN</small><strong id="stockCount">0</strong></div></div><h3>BY STOCK</h3><div id="breakdown" class="breakdown"></div><h3>NEXT PAYCHECK PURCHASES</h3><div id="upcoming" class="upcoming"></div></section><div class="ref"><b>🌱 ROBINHOOD REFERRAL</b><br><span class="muted">Optional brokerage link. Investing involves risk.</span><a href="https://join.robinhood.com/steveng-15bac4" target="_blank">OPEN ROBINHOOD →</a></div></div><script>
const stocks={stocks_json};let selected=stocks[0]||null;let mode='one';let rotation=[];const fmt=n=>'$'+Number(n).toLocaleString(undefined,{{minimumFractionDigits:2,maximumFractionDigits:2}});function renderStocks(){{document.getElementById('stocks').innerHTML=stocks.map(s=>`<button class="stock ${{selected&&selected.ticker===s.ticker?'active':''}}" onclick="pick('${{s.ticker}}')"><span class="badge">${{s.rank}}</span><span class="stockMain"><span class="stockName">${{s.name}}</span><br><span class="ticker">${{s.ticker}} • AI Score ${{s.score}}</span></span><span class="price">${{fmt(s.price)}}</span></button>`).join('')}}function pick(t){{selected=stocks.find(s=>s.ticker===t);document.getElementById('selected').innerHTML=`Selected: <span class="cyan">${{selected.name}} (${{selected.ticker}})</span> at ${{fmt(selected.price)}}`;renderStocks()}}function setMode(m){{mode=m;document.getElementById('oneBtn').classList.toggle('active',m==='one');document.getElementById('rotBtn').classList.toggle('active',m==='rotation');document.getElementById('rotation').classList.toggle('show',m==='rotation')}}function setAmt(a){{document.getElementById('amount').value=a}}function addRotation(){{if(rotation.length>=5)return;let t=document.getElementById('rotSelect').value,s=stocks.find(x=>x.ticker===t);if(s)rotation.push(s);renderRoute()}}function clearRotation(){{rotation=[];renderRoute()}}function renderRoute(){{document.getElementById('route').innerHTML=rotation.map((s,i)=>`<span class="pill">${{i+1}}. ${{s.ticker}}</span>`).join('')}}function calculate(){{let amt=Number(document.getElementById('amount').value),days=Number(document.getElementById('freq').value),start=new Date(document.getElementById('start').value+'T12:00:00'),end=new Date(document.getElementById('end').value+'T12:00:00'),plan=mode==='rotation'?rotation:[selected];if(!amt||!plan.length||isNaN(start)||isNaN(end)||end<start){{alert('Choose your stock plan, amount, start date and end date.');return}}let dates=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+days))dates.push(new Date(d));let by={{}};dates.forEach((d,i)=>{{let s=plan[i%plan.length];if(!by[s.ticker])by[s.ticker]={{s,contrib:0,shares:0,count:0}};by[s.ticker].contrib+=amt;by[s.ticker].shares+=amt/s.price;by[s.ticker].count++}});let total=dates.length*amt,val=Object.values(by).reduce((a,x)=>a+x.shares*x.s.price,0);document.getElementById('contrib').textContent=fmt(total);document.getElementById('deposits').textContent=dates.length;document.getElementById('value').textContent=fmt(val);document.getElementById('stockCount').textContent=Object.keys(by).length;document.getElementById('resultTitle').textContent=mode==='rotation'?'YOUR ROTATION SUMMARY':'YOUR '+selected.ticker+' PLAN';document.getElementById('breakdown').innerHTML=Object.values(by).map(x=>`<div class="breakrow"><span>${{x.s.name}} (${{x.s.ticker}})</span><span>${{x.count}} buys • ${{fmt(x.contrib)}} • ${{x.shares.toFixed(4)}} shares</span></div>`).join('');document.getElementById('upcoming').innerHTML=dates.slice(0,10).map((d,i)=>{{let s=plan[i%plan.length];return `<div class="deposit"><span>${{d.toLocaleDateString()}}</span><span><b>${{s.ticker}}</b> • ${{fmt(amt)}} • ${{(amt/s.price).toFixed(4)}} shares</span></div>`}}).join('');document.getElementById('results').classList.add('show');document.getElementById('results').scrollIntoView({{behavior:'smooth'}})}}document.getElementById('rotSelect').innerHTML=stocks.map(s=>`<option value="${{s.ticker}}">${{s.name}} (${{s.ticker}})</option>`).join('');let now=new Date();document.getElementById('start').value=now.toISOString().slice(0,10);pick(stocks[0].ticker);renderStocks();
</script></body></html>'''
components.html(html,height=5200,scrolling=False)
